import{_ as r,a0 as s,w as i,s as l,I as o,x as a,a1 as n,A as p,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat","title":"如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址","tag":"201504","desc":""},"relativePath":"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat.md","filePath":"[post].md"}'),d={name:"201504/20150202 How to Bind Apache Tomcat to IPv4 in Centos or Redhat.md"};function c(h,t,u,v,T,P){const e=s("Link");return i(),l("div",null,[t[20]||(t[20]=o("h1",{id:"如何在-centos-rhel-中為-apache-tomcat-綁定-ipv4-地址",tabindex:"-1"},[a("如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址 "),o("a",{class:"header-anchor",href:"#如何在-centos-rhel-中為-apache-tomcat-綁定-ipv4-地址","aria-label":"Permalink to “如何在 CentOS/RHEL 中為 Apache Tomcat 綁定 IPv4 地址”"},"​")],-1)),t[21]||(t[21]=o("p",null,"今天我們來學習一下如何在CentOS 7 Linux分佈式系統中為Tomcat綁定IPv4。",-1)),o("p",null,[t[1]||(t[1]=o("strong",null,"Apache Tomcat",-1)),t[2]||(t[2]=a(" 是由",-1)),n(e,{href:"http://www.apache.org/"},{default:p(()=>[...t[0]||(t[0]=[a("Apache 軟件基金會",-1)])]),_:1}),t[3]||(t[3]=a(" 開發的開源web服務器和servlet容器。它實現了Java Servlet，JavaServer頁面（JSP），Java的統一表達式語言，以及Sun Microsystems的Java的WebSocket規範，並提供了一個運行java代碼的web服務器環境。",-1))]),t[22]||(t[22]=o("p",null,"如果由於tomcat默認綁定到IPv6而導致我們的web服務器不能正常工作，就有必要將tomcat綁定到IPv4。眾所周知，IPv6是為設備分配IP地址的現代方法，雖然在不久的將來也許會得到應用，但是現在並沒有得到完全應用。由於沒有用處，目前我們並不需要將我們的Tomcat服務器向IPv6轉換，我們應該將其綁定到IPv4。",-1)),o("p",null,[t[5]||(t[5]=a("在開始將tomcat綁定到IPv4之前，我們應該確保在我們的CentOS 7中已經安裝了tomcat。可以看這個",-1)),n(e,{href:"http://linoxide.com/linux-how-to/install-tomcat-8-centos-7/"},{default:p(()=>[...t[4]||(t[4]=[a("如何在CentOS 7.0服務器中安裝tomcat 8",-1)])]),_:1}),t[6]||(t[6]=a("的指導。",-1))]),t[23]||(t[23]=m(`<h3 id="_1-切換到tomcat用户" tabindex="-1">1. 切換到tomcat用户 <a class="header-anchor" href="#_1-切換到tomcat用户" aria-label="Permalink to “1. 切換到tomcat用户”">​</a></h3><p>首先，我們要切換到 <strong>tomcat</strong> 用户。我們可以通過在shell或者終端中運行 <strong>su tomcat</strong> 命令完成。</p><pre><code># su tomcat
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/switch-user-tomcat.png" alt="切換到tomcat用户"></p><h3 id="_2-找到文件-catalina-sh" tabindex="-1">2. 找到文件 Catalina.sh <a class="header-anchor" href="#_2-找到文件-catalina-sh" aria-label="Permalink to “2. 找到文件 Catalina.sh”">​</a></h3><p>現在我們要進入Apache Tomcat安裝目錄下的bin文件夾，通常是 <strong>/usr/share/apache-tomcat-8.0.x/bin/</strong>， 這裏的x是 Apache Tomcat發行版的子版本號。因為我的CentOS 7服務器中安裝的版本是8.0.18，這裏我的目錄是 <strong>/usr/share/apache-tomcat-8.0.18/bin/</strong>。</p><pre><code>$ cd /usr/share/apache-tomcat-8.0.18/bin
</code></pre><p><strong>注意：請用你係統中安裝的Apache Tomcat的版本號替換8.0.18。</strong></p><p>在bin目錄中，有一個名字是catalina.sh的腳本文件。這就是我們要編輯的文件，我們將在裏面增加一行將tomcat綁定到IPv4的配置信息。你可以通過在shell或者終端中運行命令 <strong>ls</strong> 來查看這個文件。</p><pre><code>$ ls
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/finding-catalina.sh_.png" alt="查找文件 catalina.sh"></p><h3 id="_3-配置-catalina-sh" tabindex="-1">3. 配置 Catalina.sh <a class="header-anchor" href="#_3-配置-catalina-sh" aria-label="Permalink to “3. 配置 Catalina.sh”">​</a></h3><p>如圖所示，我們將在catalina.sh腳本文件的最後增加一行 <code>JAVA_OPTS= &quot;$JAVA_OPTS -Djava.net.preferIPv4Stack=true -Djava.net.preferIPv4Addresses&quot;</code>。我們可以使用我們喜歡的文本編輯器來編輯這個文件，例如nano、vim等等。這裏我們使用nano。</p><pre><code>$ nano catalina.sh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/catalina-script.png" alt="Catalina script"></p><p>然後，如下圖所示，將該行增加到文件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/configured-catalina.png" alt="配置 catalina"></p><p>現在，我們已經將配置信息增加到文件中。保存文件並退出nano。</p><h3 id="_4-重啓" tabindex="-1">4. 重啓 <a class="header-anchor" href="#_4-重啓" aria-label="Permalink to “4. 重啓”">​</a></h3><p>現在，我們通過重啓tomcat服務器使配置生效。我們要先運行shutdown.sh，然後運行startup.sh。</p><pre><code>$ ./shutdown.sh
</code></pre><p>運行可執行文件startup.sh:</p><pre><code>$ ./startup.sh
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/restarting-tomcat-server.png" alt="重啓apache tomcat 服務器"></p><p>這將重啓我們的tomcat服務器並加載將服務器綁定到IPv4的配置信息。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>好了，我們終於將我們運行在CentOS 7 Linux發行版上的tomcat服務器綁定到IPv4上了。儘管IPv6在不久的將來也許會得到應用，但由於現在還沒有使用，如果因為將你的Tomcat服務器綁定到IPv6上而使得你的tomcat服務器不工作，就有必要將tomcat綁定到IPv4上，這也很簡單。如果你有任何疑問，建議，反饋，請在下面的評論框中寫下來，讓我們知道有什麼需要增加或者改進。非常感謝！</p><hr>`,28)),o("p",null,[t[8]||(t[8]=a("via: ",-1)),n(e,{href:"http://linoxide.com/linux-how-to/bind-apache-tomcat-ipv4-centos/"},{default:p(()=>[...t[7]||(t[7]=[a("http://linoxide.com/linux-how-to/bind-apache-tomcat-ipv4-centos/",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=a("作者：",-1)),n(e,{href:"http://linoxide.com/author/arunp/"},{default:p(()=>[...t[9]||(t[9]=[a("Arun Pyasi",-1)])]),_:1}),t[13]||(t[13]=a(" 譯者：",-1)),n(e,{href:"https://github.com/ictlyh"},{default:p(()=>[...t[10]||(t[10]=[a("ictlyh",-1)])]),_:1}),t[14]||(t[14]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[11]||(t[11]=[a("wxy",-1)])]),_:1})]),o("p",null,[t[17]||(t[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[a("LCTT",-1)])]),_:1}),t[18]||(t[18]=a(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[a("Linux中國",-1)])]),_:1}),t[19]||(t[19]=a(" 榮譽推出",-1))])])}const x=r(d,[["render",c]]);export{f as __pageData,x as default};
